import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Caching","description":"","frontmatter":{},"headers":[],"relativePath":"de/advanced/caching.md","filePath":"de/advanced/caching.md","lastUpdated":1784903584000}'),s={name:"de/advanced/caching.md"};function r(c,e,h,d,l,o){return i(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h1><h2 id="ubersicht" tabindex="-1">Übersicht <a class="header-anchor" href="#ubersicht" aria-label="Permalink to &quot;Übersicht&quot;">​</a></h2><p>swag2mcp speichert heruntergeladene Spezifikationsdateien zwischen, damit der MCP-Server bei nachfolgenden Starts schneller startet. Anstatt jedes Mal dieselbe Spezifikationsdatei herunterzuladen, wird die zwischengespeicherte Kopie wiederverwendet.</p><h2 id="wie-caching-funktioniert" tabindex="-1">Wie Caching funktioniert <a class="header-anchor" href="#wie-caching-funktioniert" aria-label="Permalink to &quot;Wie Caching funktioniert&quot;">​</a></h2><p>Wenn Sie eine Spec mit einer entfernten URL hinzufügen, lädt swag2mcp sie herunter und speichert sie im Verzeichnis <code>cache/</code>. Beim nächsten Start wird geprüft, ob die zwischengespeicherte Kopie noch aktuell ist. Wenn ja, wird der Download übersprungen.</p><h3 id="was-wird-zwischengespeichert" tabindex="-1">Was wird zwischengespeichert <a class="header-anchor" href="#was-wird-zwischengespeichert" aria-label="Permalink to &quot;Was wird zwischengespeichert&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Quelle</th><th>Verhalten</th></tr></thead><tbody><tr><td><strong>Entfernte URL</strong> (http/https)</td><td>Immer zwischengespeichert. Einmal heruntergeladen, bis zum Ablauf des Caches wiederverwendet.</td></tr><tr><td><strong>Lokale Datei in <code>specs/</code></strong></td><td>Direkt aus dem Verzeichnis <code>specs/</code> verwendet. Nie zwischengespeichert — Änderungen sind sofort sichtbar.</td></tr><tr><td><strong>Lokale Datei außerhalb <code>specs/</code></strong></td><td>In den Cache kopiert. Wenn sich die Quelldatei ändert (Änderungszeit), wird der Cache ungültig.</td></tr></tbody></table><h3 id="cache-ablauf-ttl" tabindex="-1">Cache-Ablauf (TTL) <a class="header-anchor" href="#cache-ablauf-ttl" aria-label="Permalink to &quot;Cache-Ablauf (TTL)&quot;">​</a></h3><p>Jede zwischengespeicherte Datei erhält eine zufällige Ablaufzeit zwischen <strong>1 Stunde und 48 Stunden</strong>. Die Zufälligkeit verhindert, dass alle zwischengespeicherten Dateien gleichzeitig ablaufen (was zu einer Überlastung durch gleichzeitige Downloads führen würde).</p><ul><li>Die TTL wird bei jedem Start des MCP-Servers zurückgesetzt</li><li>Wenn eine zwischengespeicherte Datei noch innerhalb ihrer TTL liegt, wird sie wiederverwendet</li><li>Wenn die TTL abgelaufen ist, wird die Datei erneut heruntergeladen</li></ul><h3 id="cache-struktur" tabindex="-1">Cache-Struktur <a class="header-anchor" href="#cache-struktur" aria-label="Permalink to &quot;Cache-Struktur&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/cache/</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.spec    # Zwischengespeicherte Spezifikationsdatei</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.meta    # Metadaten (Quelle, TTL, Cache-Zeitpunkt)</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.spec</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.meta</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><p>Der Cache-Schlüssel wird aus der URL oder dem Pfad der Spezifikationsdatei abgeleitet. Jede zwischengespeicherte Datei hat eine begleitende <code>.meta</code>-Datei, die speichert, wann sie zwischengespeichert wurde und wann sie abläuft.</p><h2 id="cache-verwalten" tabindex="-1">Cache verwalten <a class="header-anchor" href="#cache-verwalten" aria-label="Permalink to &quot;Cache verwalten&quot;">​</a></h2><h3 id="aktualisierung-erzwingen" tabindex="-1">Aktualisierung erzwingen <a class="header-anchor" href="#aktualisierung-erzwingen" aria-label="Permalink to &quot;Aktualisierung erzwingen&quot;">​</a></h3><p>Führen Sie <code>swag2mcp update</code> aus, um den gesamten Cache zu leeren und alle Spezifikationsdateien neu herunterzuladen:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>Dies validiert die Konfiguration, leert den Cache und lädt alles frisch herunter.</p><h3 id="cache-manuell-leeren" tabindex="-1">Cache manuell leeren <a class="header-anchor" href="#cache-manuell-leeren" aria-label="Permalink to &quot;Cache manuell leeren&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span></span></code></pre></div><p>Dies entfernt alle zwischengespeicherten Spezifikationsdateien und gespeicherten API-Antworten. Beim nächsten Start des MCP-Servers werden alle Spezifikationen erneut heruntergeladen.</p><h3 id="automatische-bereinigung" tabindex="-1">Automatische Bereinigung <a class="header-anchor" href="#automatische-bereinigung" aria-label="Permalink to &quot;Automatische Bereinigung&quot;">​</a></h3><p>Beim Start des MCP-Servers (<code>swag2mcp mcp</code>) werden gespeicherte API-Antworten, die älter als 48 Stunden sind, automatisch entfernt. Dies verhindert, dass das Verzeichnis <code>responses/</code> unbegrenzt wächst.</p><h2 id="wichtige-hinweise" tabindex="-1">Wichtige Hinweise <a class="header-anchor" href="#wichtige-hinweise" aria-label="Permalink to &quot;Wichtige Hinweise&quot;">​</a></h2><ul><li><strong>Lokale Dateien in <code>specs/</code> werden nie zwischengespeichert</strong> — wenn Sie eine Spezifikationsdatei direkt im Verzeichnis <code>specs/</code> bearbeiten, sind die Änderungen sofort sichtbar, ohne den Cache zu leeren</li><li><strong>Entfernte URLs werden immer zwischengespeichert</strong> — es gibt keine Möglichkeit, den Cache für entfernte URLs zu umgehen, außer durch Ausführen von <code>swag2mcp update</code> oder <code>swag2mcp clean</code></li><li><strong>Der Cache ist lokal</strong> — er wird auf der Festplatte gespeichert und nicht zwischen Rechnern synchronisiert. Verwenden Sie <code>swag2mcp export</code> und <code>swag2mcp import</code>, um Spezifikationen zwischen Rechnern zu übertragen</li></ul>`,25)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
